import {ARCHIVES,newRecord,reviewRecord,profileExport,safeUrl} from './profile-core.js';
const KEY='family-history-research-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={},loadError='';
try{const saved=JSON.parse(localStorage.getItem(KEY)||'{}');if(!saved||typeof saved!=='object'||Array.isArray(saved)||Object.values(saved).some(v=>!Array.isArray(v.searches)||!Array.isArray(v.records)))throw Error();data=saved;}catch{loadError='Saved research could not be read. Export or recover browser storage before adding records.';}
const blank=()=>({searches:[],records:[]});
export function mountProfile(root,person,relationships,places){
 const section=document.createElement('section');section.className='profile-research';root.insertBefore(section,root.querySelector('.panel-heading'));let tab='timeline';
 const get=()=>data[person.id]||blank();
 function save(next){if(loadError)throw Error(loadError);const updated={...data,[person.id]:next};localStorage.setItem(KEY,JSON.stringify(updated));data=updated;}
 function message(text){section.querySelector('[role=status]').textContent=text;}
 function draw(){const research=get(),profile=profileExport(person,relationships,places,research);
 section.innerHTML=`<div class="profile-tabs" role="group" aria-label="Person research"><button data-tab="timeline" aria-pressed="${tab==='timeline'}">Timeline</button><button data-tab="sources" aria-pressed="${tab==='sources'}">Sources (${research.records.length})</button><button data-export aria-label="Export person as structured JSON">↓ JSON</button></div><p role="status">${esc(loadError)}</p><div class="research-content"></div>`;
 section.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;draw();});
 section.querySelector('[data-export]').onclick=()=>{const blob=new Blob([JSON.stringify(profile,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`person-${person.id}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 const content=section.querySelector('.research-content');
 if(tab==='timeline')content.innerHTML=profile.person.events.map(e=>`<div class="event"><span>${esc(e.date||'Date unknown')} · ${esc(e.type)}</span>${esc(e.place||'Place not recorded')}<p>${esc(e.description||'')}</p><small>${esc(e.status)}${e.sourceIds.length?' · source attached':''}</small>${e.sourceIds.length?'<button data-source-jump>View source</button>':''}</div>`).join('')||'<p>No events recorded yet.</p>';
 else content.innerHTML=`<p class="panel-note">Searches open archive websites. Use the query below there, then attach what you found. No automatic results retrieval. Nothing is added until you review it.</p><label>Research query<textarea id="research-query" rows="3">${esc(person.name+' '+(person.birth||'')+' '+(places[person.events.find(e=>e.type==='birth')?.place]?.name||''))}</textarea></label><div class="archive-links">${ARCHIVES.map(a=>`<button data-archive="${a.id}">${esc(a.name)} ↗</button>`).join('')}</div><details><summary>Attach a found record</summary><form id="record-form"><label>Related search<select name="searchId"><option value="">Other / direct source</option>${research.searches.map(s=>`<option value="${esc(s.id)}">${esc(s.provider+' · '+s.query)}</option>`).join('')}</select></label><label>Record title<input name="title" required></label><label>Event<select name="type"><option value="birth">Birth</option><option value="immigration">Immigration / landing</option><option value="residence">Residence</option><option value="death">Death</option><option value="other">Other</option></select></label><label>Date (YYYY, YYYY-MM or YYYY-MM-DD)<input name="date" placeholder="Leave blank if unknown"></label><label>Place as recorded<input name="place"></label><label>Record URL<input name="url" type="url" required></label><label>Reference / collection, volume, page<input name="reference" required></label><label>What was found / transcription<textarea name="finding" required rows="3"></textarea></label><button>Save as candidate</button></form></details><h3>Found records</h3>${research.records.length?'':'<p>No records attached.</p>'}${research.records.map(r=>`<article class="source-record"><strong>${esc(r.title)}</strong><small>${esc(r.status)} · ${esc(r.type)} · ${esc(r.date||'date unknown')}</small><a href="${esc(link(r.url))}" target="_blank" rel="noopener noreferrer">Open record ↗</a><p>${esc(r.reference)}</p><p>${esc(r.finding)}</p><p>${r.status==='accepted'?'Added: sourced '+esc(r.type)+' event in this person’s timeline. Existing biography and relationships retained.':r.status==='rejected'?'Not added: rejected on review.':'Not added: awaiting review.'}</p>${r.reviewNote?`<p>Review: ${esc(r.reviewNote)}</p>`:''}<button data-review="${esc(r.id)}">Review / change status</button></article>`).join('')}<h3>Search history</h3>${[...research.searches].reverse().map(s=>`<article class="source-record"><a href="${esc(link(s.url))}" target="_blank" rel="noopener noreferrer">${esc(s.provider)} ↗</a><small>${esc(s.createdAt)}</small><p>${esc(s.query)}</p><p>Search opened · ${research.records.filter(r=>r.searchId===s.id).length} records attached</p></article>`).join('')||'<p>No searches recorded.</p>'}<p class="panel-note">Research is saved only in this browser. Export JSON to keep a portable copy. Dates that disagree remain visible; acceptance means you reviewed the source, not that it is proven true.</p>`;
 content.querySelectorAll('[data-source-jump]').forEach(b=>b.onclick=()=>{tab='sources';draw();});
 content.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{try{const a=ARCHIVES.find(a=>a.id===b.dataset.archive),query=content.querySelector('#research-query').value.trim();if(!query)throw Error('Enter a research query.');const search={id:crypto.randomUUID(),provider:a.name,url:a.url,query,createdAt:new Date().toISOString(),status:'opened'};save({...get(),searches:[...get().searches,search]});window.open(a.url,'_blank','noopener,noreferrer');draw();message('Search logged. Copy the query into the archive search form.');}catch(e){message(e.message);}});
 const form=content.querySelector('#record-form');if(form)form.onsubmit=e=>{e.preventDefault();try{const record=newRecord(Object.fromEntries(new FormData(form)));save({...get(),records:[...get().records,record]});draw();message('Candidate saved. Review before adding to the timeline.');}catch(e){message(e.message);}};
 content.querySelectorAll('[data-review]').forEach(b=>b.onclick=()=>{const record=get().records.find(r=>r.id===b.dataset.review);const box=document.createElement('form');box.className='record-review';box.innerHTML=`<label>Decision<select name="status"><option value="candidate">Keep as candidate</option><option value="accepted">Accept into timeline</option><option value="rejected">Reject match</option></select></label><label>Identity evidence / conflicts / reason<textarea name="note" required>${esc(record.reviewNote||'')}</textarea></label><button>Save review</button>`;box.querySelector('select').value=record.status;b.replaceWith(box);box.onsubmit=e=>{e.preventDefault();try{const f=new FormData(box),updated=reviewRecord(record,f.get('status'),f.get('note'));save({...get(),records:get().records.map(r=>r.id===record.id?updated:r)});draw();message('Review saved. Timeline and export updated.');}catch(e){message(e.message);}};});
 }
 draw();
}
function link(url){try{return safeUrl(url);}catch{return '#';}}
